style.css:
@-moz-document domain("weather.com") {
/* weather.com is a hashed CSS-module React SPA: styled class names rotate on every
     deploy. Build ONLY on stable hooks -- design-system custom properties, Tailwind
     utilities, data-testid attributes, and CSS-module name PREFIXES (only the trailing
     build-hash rotates). HANDS OFF the data: maps, condition icons, the temperature
     scale, AQI / UV / pollen codes and alert banners. */

  :root {
    color-scheme: dark;

    --wx-base: #14181d;          /* page base                     */
    --wx-surface: #1c2128;       /* cards / modules               */
    --wx-surface-2: #161d27;     /* alt elevated / wells / zebra  */
    --wx-chrome: #0d1117;        /* header / footer / sidebar     */
    --wx-border: #262c33;        /* subtle border                 */
    --wx-border-2: #2d333b;      /* component border              */
    --wx-text: #e6edf3;          /* primary text                  */
    --wx-text-2: #c4cdd6;        /* body text                     */
    --wx-text-muted: #8b949e;    /* metadata / muted              */
    --wx-link: #5fb0e6;          /* refined weather.com blue      */
    --wx-link-hover: #9bd4ff;

    /* design-system tokens (shadcn / Tailwind v4) */
    /* the app consumes these as bg-card / bg-background / text-foreground /
       border-border, so a remap themes most of it. */
    --background: #14181d !important;
    --foreground: #e6edf3 !important;
    --card: #1c2128 !important;
    --card-foreground: #e6edf3 !important;
    --popover: #1c2128 !important;
    --popover-foreground: #e6edf3 !important;
    --primary: #5fb0e6 !important;
    --primary-foreground: #0d1117 !important;
    --secondary: #1c2128 !important;
    --secondary-foreground: #e6edf3 !important;
    --muted: #161d27 !important;
    --muted-foreground: #8b949e !important;
    --accent: #1c2128 !important;
    --accent-foreground: #e6edf3 !important;
    --border: #262c33 !important;
    --input: #2d333b !important;
    --ring: #5fb0e6 !important;
    --text-secondary: #8b949e !important;
  }

  /* base */
  html,
  body,
  #app,
  #appWrapper,
  main,
  [data-testid="page-wrapper"] {
    background-color: var(--wx-base) !important;
    color: var(--wx-text-2) !important;
  }

  /* specific borders are re-handled below; maps / charts are excluded at the bottom. */
  * {
    border-color: var(--wx-border) !important;
  }
  /* ...but these are semantic: `border-black` marks the SELECTED unit in the unit
     picker (siblings are `border-transparent`), `border-white` is the map pin's ring. */
  .border-transparent {
    border-color: transparent !important;
  }
  .border-black,
  .border-white {
    border-color: var(--wx-text) !important;
  }
  /* ...but this ring is an INVISIBLE spacer on the article body: painting it draws a
     halo the site never shows. Keep the ring, drop the paint. */
  img[class*="authorImage"] {
    border-color: transparent !important;
  }
  /* a real affordance the blanket rule pins flat; on dark the equivalent of the site's
     darken is to brighten. */
  [class*="hover:border-gray-300"]:hover,
  [class*="hover:border-gray-400"]:hover,
  [class*="hover:border-gray-500"]:hover,
  [class*="hover:border-black"]:hover {
    border-color: var(--wx-text-muted) !important;
  }
  /* a chromatic accent the blanket reset would erase; #679ced reads on dark. Both hex
     spellings: the attribute match is case-sensitive. */
  [class*="border-[#679CED]"],
  [class*="border-[#679ced]"] {
    border-color: #679ced !important;
  }

  /* header / sidebar chrome */
  [data-testid="header-main"],
  [data-component="header-main"],
  header,
  [data-testid="subnavigation"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text) !important;
  }

  /* the skip-nav reveals a WHITE pill on keyboard focus, so darken the pill rather
     than recolour the link on it. */
  [class*="MainMenuHeader--accessibilityLink"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-link) !important;
  }

  /* KNOCKOUT logo: one evenodd <path> paints the blue square and the letters are
     HOLES, so the glyphs are whatever sits behind the svg -- hence a white backdrop
     BEHIND it rather than a fill. Three carriers, one per frontend; the bare
     support.weather.com <svg> is identified only by its 48x48 viewBox, and the Weather
     Underground tile beside it is 50x50 and must NOT take a white plate. */
  svg[class*="text-[#003399]"],
  svg[class*="SidebarNavigation--logoIcon"],
  .brands svg[viewBox="0 0 48 48"] {
    background-color: #ffffff !important;
  }

  /* left sidebar navigation rail */
  [data-testid="sidebar-navigation"],
  [data-component="sidebar-navigation"],
  nav[data-testid="sidebar-navigation"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text-2) !important;
  }
  /* sidebar links + their hover/active fills (ship bg-gray-100 / f2f2f2) */
  [data-testid="sidebar-navigation"] a,
  [data-testid="sidebar-navigation"] button {
    background-color: transparent !important;
    color: var(--wx-text-2) !important;
  }
  [data-testid="sidebar-navigation"] a:hover,
  [data-testid="sidebar-navigation"] button:hover {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text) !important;
  }
  /* brand blue on label AND icon (`text-inherit`) marks the current page; #3a61cc is
     2.9:1 on the dark pill, so use the link blue. */
  [data-testid="sidebar-navigation"] a[aria-current],
  [data-testid="sidebar-navigation"] [aria-current="page"],
  [data-testid="sidebar-navigation"] a.bg-gray-100 {
    background-color: var(--wx-surface) !important;
    color: var(--wx-link) !important;
  }
  /* the label is a <p> the generic `p` rule repaints, so it needs colouring with its
     item (no fill: the pill already has one). */
  [data-testid="sidebar-navigation"] a[aria-current] p,
  [data-testid="sidebar-navigation"] [aria-current="page"] p,
  [data-testid="sidebar-navigation"] a.bg-gray-100 p {
    color: var(--wx-link) !important;
  }
  /* the LEGACY rail shares the data-testid but marks the current page with a `--active`
     pill and no aria-current. That pill is its ONLY marker, so restore the fill alone. */
  [data-testid="sidebar-navigation"] a[class*="SidebarNavigation--active"] {
    background-color: var(--wx-surface) !important;
  }
  /* the location-pill popover anchor (rounded-4xl bg-white wrapper) */
  [data-slot="popover-anchor"],
  .rounded-4xl.bg-white {
    background-color: var(--wx-surface) !important;
  }

  /* the wrapper is full viewport height while the nav is ~636px, so a bright strip
     shows below the nav items. */
  .region-sidebarNavigation,
  .regionSidebarNavigation,
  [class*="SidebarNavigation--sidebarWrapper"],
  [class*="SidebarNavigation--sidebar"] {
    background-color: var(--wx-chrome) !important;
  }
  /* CRITICAL: `--isOverlay` is that same wrapper as a fixed, full-viewport,
     pointer-events:none layer that is normally TRANSPARENT (the closed mobile-overlay
     backdrop). Opaque, it covers the page. */
  [class*="SidebarNavigation--isOverlay"] {
    background-color: transparent !important;
  }

  /* legacy "Daybreak" surfaces (Monthly and other unmigrated routes): the old Helios
     layout, which no new-layout token or utility touches. Matched by stable module prefix;
     condition icons and temperatures keep their hues. */
  [class*="Card--card"],
  /* this prefix also lands on the nav's "View" button, whose fill + ink pair IS the
     enabled/disabled cue, so it is exempt. */
  [class*="CalendarMonthPicker--"]:not([class*="viewButton"]),
  [class*="DailyForecast--"],
  /* id-prefixed forms out-rank module CSS-in-JS rules injected after our sheet, which
     otherwise win same-specificity ties. */
  [id^="Wxu"] [class*="Card--card"],
  aside[class*="region-sidebar"],
  aside[class*="regionSidebar"],
  [class*="Layers--overlayGroup"],
  /* the 404 fallback (e.g. an alerts URL with no active alerts) renders white teaser
     cards. */
  [class*="NotFound--pageLink"],
  [class*="NotFound--notFound"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  #regionHeader,
  [class*="region-header"],
  [class*="regionHeader"] {
    background-color: var(--wx-chrome) !important;
  }
  [class*="DaypartDetails--DetailsTable"],
  [class*="DetailsTable--"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="Calendar--line"] {
    background-color: var(--wx-border) !important;
  }
  /* the grid comes from a module rule with !important, so `* { border-color }` loses;
     card-scoped to out-rank later-injected module rules. */
  [class*="Card--card"] [class*="CalendarDateCell"],
  [class*="Card--card"] [class*="DetailsTable--listItem"],
  [class*="CalendarDateCell--dayCell"] {
    border-color: var(--wx-border) !important;
  }
  /* the week-divider border-top comes from a separate, higher-specificity [dir]-prefixed
     rule, so it needs the gridWrapper ancestor + button tag and border-top-color pinned. */
  [class*="Card--card"] [class*="Calendar--gridWrapper"] button[class*="CalendarDateCell--dayCell"],
  [class*="Calendar--gridWrapper"] button[class*="CalendarDateCell--dayCell"] {
    border-color: var(--wx-border) !important;
    border-top-color: var(--wx-border) !important;
  }
  /* a high-specificity module rule that beats the generic `input` override. */
  #headerSearch_LocationSearch_input,
  input[id*="LocationSearch"],
  [class*="SearchInput--SearchInput"] {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  /* a `div`, not a <footer> tag, and its white fill comes from a CSS-in-JS rule injected
     AFTER our sheet, so the id-prefixed descendant form is needed to out-rank it. */
  [id^="WxuFooter"] [class*="Footer--container"],
  [class*="Footer--container"] {
    background-color: var(--wx-chrome) !important;
  }
  [class*="adBackground"],
  [class*="combinedTopAds"],
  /* the slot's own rgba(255,255,255,.5) composites to a mid-grey band wider than the
     banner in it, and is `visibility: hidden` until served. */
  .ci-adhesion {
    background-color: var(--wx-surface-2) !important;
  }
  /* filled, the slot gains a `ci-<id>-open` body class and a (0,2,0) white rule beating
     the one above. The numeric id rotates per creative; the `ci-ad-` prefix does not. */
  div[class*="ci-adhesion"][class*="ci-ad-"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* a legal disclosure, so it must stay readable. The top slot draws its label through a
     ::after content string, with no text node. */
  .adLabel,
  [class*="BaseAd--adLabel"] {
    color: var(--wx-text-muted) !important;
  }
  [class*="combinedTopAdsPlaceholder"]::after {
    color: var(--wx-text-muted) !important;
  }
  /* single-column <th> cells, so the generic `th` chrome fill would paint a black
     rectangle hugging the words; the site leaves them transparent. */
  [class*="Almanac--tableTitle"] {
    background-color: transparent !important;
  }
  /* the row border comes from a [dir]-prefixed module rule at (0,2,0), out-ranking
     `* { border-color }` at (0,0,0) -- match one class deeper to win. */
  [class*="Card--card"] tr[class*="Almanac--row"] {
    border-bottom-color: var(--wx-border) !important;
  }
  /* ~3.4:1 on our dark card; the high/low temps stay as-is. */
  [class*="CalendarDateCell--date"] {
    color: var(--wx-text-muted) !important;
  }
  /* the "Avg" caption on future / no-forecast day cells ships the same #6f7585. */
  [class*="CalendarDateCell--label"] {
    color: var(--wx-text-muted) !important;
  }
  /* the SELECTED day is a brand-blue chip labelled WHITE and carries `--date` too, so
     the muted lift above lands at 2.11:1. Compounded with the base class to out-rank it
     whatever the source order. */
  [class*="CalendarDateCell--date"][class*="CalendarDateCell--selected"] {
    color: #ffffff !important;
  }
  /* the temps and precip values keep their own colours. */
  [class*="Almanac--header"] {
    color: var(--wx-text) !important;
  }
  [class*="Almanac--recordYear"] {
    color: var(--wx-text-muted) !important;
  }

  /* the INTERNATIONAL locales (same domain, so inside this block) never migrated:
     their Today page is the legacy TodayDetailsCard, which paints both label and value
     with the Helios ink. Both inks are achromatic natively, so one uniform lift invents
     no hue. Wind and Pressure carry the ink on their own wrapper span, so a matched rule
     is needed to beat the row's inherited colour. */
  [data-testid="WeatherDetailsListItem"] [class*="WeatherDetailsListItem--label"],
  [data-testid="WeatherDetailsListItem"] [class*="WeatherDetailsListItem--wxData"],
  [data-testid="WeatherDetailsListItem"] [class*="Wind--windWrapper"],
  [data-testid="WeatherDetailsListItem"] [class*="Pressure--pressureWrapper"],
  /* the day-part table under it puts the chance-of-rain cell at #2b2b2b. */
  [class*="Column--precip"],
  /* the legacy Air Quality page ships the same ink on its info link and the legend
     popover's "Source" title. */
  [class*="AirQuality--moreDetailsText"],
  [class*="AirQuality--popoverTitle"] {
    color: var(--wx-text-2) !important;
  }
  /* the "/" between the temperatures is a bare text node on the tempLo wrapper. A
     separator, not data, so muted. */
  [class*="Column--tempLo"] {
    color: var(--wx-text-muted) !important;
  }
  /* that page's per-pollutant concentration is the dimmer #6f7585 -- 3.4:1 at
     14px. */
  [class*="AirQualityText--measurement"] {
    color: var(--wx-text-muted) !important;
  }
  /* the ink sits on the anchor's own wrappers -- the `Ellipsis--ellipsis` span holding
     the words is a truncation utility with no colour. */
  [class*="CollectionMediaList--title"] {
    color: var(--wx-text) !important;
  }
  [class*="CollectionMediaList--caption"] {
    color: var(--wx-text-2) !important;
  }
  [class*="CollectionMediaList--date"] {
    color: var(--wx-text-muted) !important;
  }

  /* EVERY legacy Helios icon paints its glyph with the design system's ink three
     ways -- a literal `fill` attribute, a CSS `fill` on a path with no attribute, and
     inherited `currentColor` -- so all three need covering.
     The COLOURED icons stay safe: `WxIcon--*` condition icons paint from fill ATTRIBUTES
     (`path:not([fill])` skips them, `color` is not in their chain), and the knockout
     wordmark is excluded outright -- one of its paths is currentColor and lifting it would
     bleach the mark. `Icon--lightTheme` is Helios for "drawn for a dark backdrop" and is
     natively WHITE, so it is put back; the header magnifier carries that class but
     overrides it with its own ink, so it is re-darkened after. */
  svg[class*="Icon--icon"]:not([class*="logoIcon"]) {
    color: var(--wx-text-2) !important;
  }
  svg[class*="Icon--icon"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    fill: var(--wx-text-2) !important;
  }
  svg[class*="Icon--icon"] path[fill="#252422"],
  svg[class*="Icon--icon"] path[fill="#2B2B2B"],
  svg[class*="Icon--icon"] path[fill="#2b2b2b"] {
    fill: var(--wx-text-2) !important;
  }
  svg[class*="Icon--icon"][class*="Icon--lightTheme"] {
    color: #ffffff !important;
  }
  /* the legacy NARROW header carries the knockout wordmark as `MainMenuHeader--twcLogo`
     with that same lightTheme class, but overrides it with the brand navy: with the
     colour lifted to white the square goes white and the letters go chrome. Navy ink on
     the white backdrop above, like the other three carriers. */
  svg[class*="Icon--icon"][class*="MainMenuHeader--twcLogo"] {
    color: #003399 !important;
    background-color: #ffffff !important;
  }
  svg[class*="Icon--icon"][class*="SearchInput--searchIcon"] {
    color: var(--wx-text-2) !important;
  }
  /* a LITERAL `fill="#000"` that `path:not([fill])` skips. Only the black paths are
     re-inked; the partner's brand colours stay. */
  svg[class*="Cobranding--icon"] path[fill="#000"],
  svg[class*="Cobranding--icon"] path[fill="#000000"],
  svg[class*="Cobranding--icon"] path[fill="black"] {
    fill: var(--wx-text) !important;
  }
  /* ...and two Helios icons are NOT ink: their inherited currentColor is CHROMATIC and
     the hue is the signal. Sunrise/sunset keep their gold; the chevrons take the link
     accent (#1b4de4 is 1.9:1 here). Both need `fill` as well as `color`: their paths
     carry no fill attribute, so `path:not([fill])` above paints them directly and only a
     matched rule beats it. */
  svg[class*="Icon--icon"][class*="TwcSunChart--sunIcon"],
  svg[class*="Icon--icon"][class*="TwcSunChart--sunIcon"] path {
    color: #febc11 !important;
    fill: #febc11 !important;
  }
  svg[class*="Icon--icon"][class*="HealthActivitiesListItem--icon"],
  svg[class*="Icon--icon"][class*="HealthActivitiesListItem--icon"] path {
    color: var(--wx-link) !important;
    fill: var(--wx-link) !important;
  }
  /* this glyph's <path> has no fill attribute, so the blanket rule matches it at (0,4,2);
     the fill selector must repeat that tail plus one more simple selector. */
  svg[class*="Icon--icon"][class*="DetailsTable--moonIcon"],
  svg[class*="Icon--icon"][class*="DetailsTable--moonIcon"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    color: var(--wx-link) !important;
    fill: var(--wx-link) !important;
  }
  /* keyed to the Pagination class, NOT `Icon--actionTheme`: that theme class also sits
     on Monthly's marks, which are plain ink natively. */
  svg[class*="Icon--icon"][class*="Pagination--arrows"],
  svg[class*="Icon--icon"][class*="Pagination--arrows"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    color: var(--wx-link) !important;
    fill: var(--wx-link) !important;
  }
  /* drawn UNDER the gold sun to punch the arc stroke out behind it, so it must track the
     card it sits on. */
  [class*="TwcSunChart"] circle {
    fill: var(--wx-surface) !important;
  }

  /* a literal <span> with a #ffffff fill and no class of its own, punched through the
     hairline. Sink it into the page base. */
  [class*="SocialLogin--divider"] span {
    background-color: var(--wx-base) !important;
    color: var(--wx-text-muted) !important;
  }
  /* a literal `<span> | </span>`: punctuation, not a link, so it takes the muted ink. */
  [class*="MemberLoginForm--separator"] {
    color: var(--wx-text-muted) !important;
  }
  /* an INVALID field is marked by a 2px #eb0000 rim on the <input> and the message under
     it; the generic `input` border pin greys the rim, and #eb0000 is 3.8:1 on the base.
     Rim and message take the same lifted red as the severe-alert text so the state stays
     one signal. */
  [class*="FormInput--hasError"] input {
    border-color: #f4695c !important;
  }
  [class*="FormInput--bottomErrors"] {
    color: #f4695c !important;
  }

  /* these pin their ink to `var(--Panther)` with !important at (0,1,0), out-ranking
     the (0,0,1) anchor rule. `--Panther` also feeds legacy button FILLS and borders, so
     restore the link colour rather than remap the token, with a second simple selector to
     clear the !important. */
  [dir] [class*="DataVendors--anchorParagraphLink"],
  [dir] [class*="LinkSection--sectionLink"] {
    color: var(--wx-link) !important;
  }
  [dir] [class*="DataVendors--anchorParagraphLink"]:hover,
  [dir] [class*="LinkSection--sectionLink"]:hover {
    color: var(--wx-link-hover) !important;
  }
  /* three legacy templates paint a full-page WHITE container no card / module / well
     selector reaches. */
  [class*="PrivacySettings--container"],
  [class*="PrivacySettings--container"] [class*="Header--headerSection"],
  [class*="DsrForm--dsrContainer"],
  [class*="PromoFeaturePage--featurePage"],
  [class*="PromoFeaturePage--featuresSection"] {
    background-color: var(--wx-base) !important;
  }
  [class*="PromoFeaturePage--featuresTitle"] {
    color: var(--wx-text) !important;
  }
  /* the ExpandableMenu rule lifts these inside the units panel; standalone (the
     /data-rights sections) nothing else reaches them. */
  [class*="Disclosure--Summary"] {
    color: var(--wx-text) !important;
  }
  /* the legacy plain-text button is the brand `--Ocean` #1b4de4, 2.74:1 on the page
     base. */
  [class*="Button--plainText"] {
    color: var(--wx-link) !important;
  }
  /* the opacity .4 fade marks it disabled, so only the ink is lifted. The
     `Button--primary` + `Button--disabled` pair is opacity 1 and marks disabled by its own
     fill, so it stays native. */
  [class*="Button--disabled"]:not([class*="Button--primary"]) {
    color: var(--wx-text) !important;
  }
  /* `Button--primary` is the Helios ink under a white label, within 1.05:1 of the card,
     so it inverts with its disabled sibling. Invert it as the chart tabs and units
     radiogroup are. Two attributes to out-rank the anchor rule on the `<a>` form and the
     ExpandableMenu lift; the icon rules match the inner glyph directly, so it is
     re-pointed with the label. */
  [class*="Button--primary"]:not([class*="Button--disabled"]) {
    background-color: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  [class*="Button--primary"]:not([class*="Button--disabled"]) svg[class*="Icon--icon"],
  [class*="Button--primary"]:not([class*="Button--disabled"]) svg[class*="Icon--icon"]:not([class*="logoIcon"]):not([class*="WxIcon"]) path:not([fill]) {
    color: var(--wx-chrome) !important;
    fill: var(--wx-chrome) !important;
  }

  /* the lower "Better Decisions" panels drop to a pure-black heading + disclaimer; the
     upper ones are brand blue. */
  [class*="BetterDecisions--heading"] {
    color: var(--wx-text) !important;
  }
  [class*="BetterDecisions--disclaimerText"] {
    color: var(--wx-text-muted) !important;
  }

  /* sub-nav pill row sits in a white rounded bar */
  [data-testid="subnavigation"] a,
  [data-testid="subnavigation"] button {
    color: var(--wx-text-2) !important;
  }
  [data-testid="subnavigation"] a:hover {
    color: var(--wx-text) !important;
  }
  /* the current tab is `text-blue-500` on a grey pill, which the rule above flattens to
     the light our text rules give the inactive tabs. */
  [data-testid="subnavigation"] [aria-current="page"] {
    color: var(--wx-link) !important;
  }

  /* horizontal-scroll fade overlays (the white "more" gradients) */
  /* the fade is a `from-white` gradient, i.e. a background-IMAGE. Neutralising its white
     ORIGIN (`--color-white` / `--tw-gradient-*`) blends every such fade whatever its
     direction. */
  [class*="pointer-events-none"][class*="from-white"],
  [class*="pointer-events-none"][class*="absolute"][class*="inset-y-0"] {
    --color-white: var(--wx-base) !important;
    --tw-gradient-from: var(--wx-base) !important;
    --tw-gradient-via: var(--wx-base) !important;
  }
  /* the chart tab strip's fades are literal `linear-gradient(to right/left, #fff 36px,
     transparent)`, so the image is overridden too. An edge fade is anchored to ONE side;
     an overlay anchored on BOTH is a full-width layer -- the radar map's control layer is
     `inset-y-0 left-0 right-0` at rest and `left-[370px]` with the Map Menu open, ships no
     background, and must never take this image or the basemap is veiled. The exclusion is
     the OTHER side's PREFIX (`left-`/`right-`), not `left-0`, so the open-menu variant
     stays excluded. */
  [class*="pointer-events-none"][class*="absolute"][class*="inset-y-0"][class*="left-0"]:not([class*="right-"]) {
    background-image: linear-gradient(to right, var(--wx-base) 36px, rgba(20, 24, 29, 0) 100%) !important;
  }
  [class*="pointer-events-none"][class*="absolute"][class*="inset-y-0"][class*="right-0"]:not([class*="left-"]) {
    background-image: linear-gradient(to left, var(--wx-base) 36px, rgba(20, 24, 29, 0) 100%) !important;
  }
  /* this button's own background IS the fade, so it resolves to the card surface. The
     site writes it !important from a `[dir="ltr"] .class` rule, so the override needs a
     third simple selector. */
  [dir] [class*="Carousel--arrowContainer"][class*="Left"] {
    background-image: linear-gradient(270deg, rgba(28, 33, 40, 0), var(--wx-surface)) !important;
  }
  [dir] [class*="Carousel--arrowContainer"][class*="Right"] {
    background-image: linear-gradient(90deg, rgba(28, 33, 40, 0), var(--wx-surface)) !important;
  }

  /* Tailwind surface utilities (stable, non-hashed) */
  /* on wells, cards and tiles. Excluded: maps / svg / canvas (handled below). */
  .bg-white,
  .bg-card,
  .bg-popover,
  [data-slot="card"],
  [data-slot="popover"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  .bg-gray-100,
  .bg-gray-50,
  .bg-neutral-100,
  .bg-slate-100,
  .bg-muted,
  .bg-secondary,
  .bg-accent {
    background-color: var(--wx-surface-2) !important;
  }
  /* a light shadow over the dark article body is a halo, not a shadow, so it takes a
     black one of the same geometry. */
  [class*="shadow-[0_3px_20px_0_rgba(181,171,162,0.5)]"] {
    box-shadow: 0 3px 20px 0 rgba(0, 0, 0, 0.55) !important;
  }
  /* -200/-300 are one step STRONGER than -100 on white, so one step LIGHTER here, and
     they are rail/track fills rather than card surfaces. */
  .bg-gray-200,
  .bg-gray-300,
  .bg-neutral-200,
  .bg-neutral-300 {
    background-color: var(--wx-border) !important;
  }
  /* `bg-black/N` veils are a few percent of BLACK over white, so mirror them to white.
     Only the LOW alphas are plates; /30 and up are scrims over photos and must stay black.
     `[class~=]` matches a whole class token, so `bg-black/5` cannot catch `bg-black/50`. */
  [class~="bg-black/5"],
  [class~="bg-black/8"],
  [class~="bg-black/10"] {
    background-color: rgba(230, 237, 243, 0.06) !important;
  }
  [class~="hover:bg-black/5"]:hover,
  [class~="hover:bg-black/14"]:hover,
  [class~="hover:bg-black/20"]:hover,
  [class~="hover:bg-black/[0.12]"]:hover {
    background-color: rgba(230, 237, 243, 0.12) !important;
  }
  [class~="active:bg-black/5"]:active,
  [class~="active:bg-black/[0.2]"]:active {
    background-color: rgba(230, 237, 243, 0.2) !important;
  }
  /* an arbitrary class no named `.bg-gray-*` utility matches, under labels our text
     rules lift. */
  [class*="bg-[#ebecee]"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* trust.weather.com (privacy / terms) sets its intro callout as a pale-blue arbitrary
     hex under paragraphs the text rules lift, and its Expand / Collapse controls as navy
     <button>s that `button { color: inherit }` greys. Matched on the hex PREFIX so the
     alpha variants (`bg-[#CBDEF080]`) resolve with it; both spellings ship. */
  [class*="bg-[#cbdef0"],
  [class*="bg-[#CBDEF0"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="text-[#039]"],
  [class*="text-[#003399]"] {
    color: var(--wx-link) !important;
  }
  /* the PALE brand tints are light surfaces; the SATURATED brand blues are real fills.
     The alpha variants have their own class TOKEN (`bg-brand-100/30`) the plain class
     selector misses -- hence the substring form. --color-brand-200 is NOT a tint: it is
     #679ced, a real mid-blue fill under white text, so it keeps its own colour like
     -300/-400. */
  .bg-brand-50,
  .bg-brand-100,
  [class*="bg-brand-100/"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* translucent white veils used as gradient/scrim fills over photos */
  .bg-white\/75,
  .bg-white\/80,
  .bg-white\/90 {
    background-color: rgba(28, 33, 40, 0.85) !important;
  }
  /* dark utility surfaces the app already uses keep a tone matching the chrome */
  .bg-gray-900,
  .bg-black {
    background-color: var(--wx-chrome) !important;
  }
  /* ...but the Sign-in CTA is a `bg-gray-900` plate SITTING ON the chrome, and both
     header layouts lose it: the rail's `a { background: transparent }` blanks it, and at
     <=md the rule above resolves it to the header's own colour. */
  [data-testid="sidebar-navigation"] a.bg-gray-900,
  [data-testid="sidebar-navigation"] a.bg-black,
  header .bg-gray-900,
  header .bg-black {
    background-color: var(--wx-surface) !important;
  }
  [data-testid="sidebar-navigation"] a.bg-gray-900:hover {
    background-color: var(--wx-border-2) !important;
  }
  /* HOVER-VARIANT fills compile to variant-prefixed names the plain `.bg-gray-100` rule
     does not match. */
  [class*="hover:bg-gray-100"]:hover,
  [class*="hover:bg-gray-200"]:hover,
  [class*="hover:bg-gray-50"]:hover,
  [class*="hover:bg-neutral-100"]:hover,
  [class*="hover:bg-neutral-200"]:hover {
    background-color: var(--wx-surface-2) !important;
  }
  /* the site's move is transparent -> a full-contrast plate, so match that with the
     component border tone; the near-base surface would read as no change. The chart tab
     strip pairs it with `hover:!bg-gray-900`, whose layered !important outranks this
     unlayered one, so the selected tab keeps its light pill. */
  [class~="hover:bg-white"]:hover {
    background-color: var(--wx-border-2) !important;
  }
  /* a control already `bg-gray-100` at rest stepping one shade down on hover lands both
     states on the same value. Three classes to out-rank both rules. */
  [class*="bg-gray-100"][class*="hover:bg-gray-200"]:hover,
  [class*="bg-gray-50"][class*="hover:bg-gray-100"]:hover {
    background-color: var(--wx-border-2) !important;
  }
  /* the same greys arrive through FOCUS and ACTIVE variants too. Matched on plain
     `:focus`, a superset of `:focus-visible` and the CSS2 form the userstyles.org parser
     accepts. `active:bg-[#E6E6E6]` is on the hero CTAs, whose press is their only
     feedback: our unlayered `.bg-white` !important outranks that layered utility, so it
     has to be restated. */
  [class~="focus:bg-gray-100"]:focus,
  [class~="focus-visible:bg-gray-100"]:focus,
  [class~="active:bg-gray-100"]:active,
  [class~="active:bg-gray-200"]:active,
  [class~="active:bg-gray-300"]:active,
  [class~="active:bg-[#E6E6E6]"]:active,
  [class~="max-sm:active:bg-gray-100"]:active {
    background-color: var(--wx-surface-2) !important;
  }

  /* segmented tab strips */
  /* the SELECTED tab is `!bg-gray-900`, whose !important sits inside the utilities
     cascade LAYER and beats our unlayered override whatever the specificity -- and raw
     #252422 matches our card's luminance. It resolves `var(--color-gray-900)`, and
     variable resolution is layer-agnostic, so redefining the token ON the tab computes our
     value while their rule still wins. Keyed to the `!` utility rather than aria-selected,
     because the LEGACY `role="tab"` unit picker is a transparent tab marked by an
     underline, where dark ink would erase the label. */
  [role="tab"][class~="!bg-gray-900"] {
    --color-gray-900: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  /* the units radiogroup is the same control with a plain (un-`!`) `bg-gray-900` checked
     pill: both remaps land one step apart, so the chip vanishes into its track. Keyed to
     aria-checked so unchecked options keep the transparent track. */
  [role="radio"][aria-checked="true"][class~="bg-gray-900"] {
    background-color: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  /* `md:hidden`, i.e. below 768px only. `data-[state=inactive]:bg-gray-100` is a class
     token no plain `.bg-gray-*` selector matches, and it is in the list in BOTH states, so
     it must be paired with the state attribute. */
  [class~="data-[state=inactive]:bg-gray-100"][data-state="inactive"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class~="data-[state=inactive]:text-gray-600"][data-state="inactive"] {
    color: var(--wx-text-muted) !important;
  }
  /* the focus RING is a box-shadow, past the border reset, and #3a61cc is under the 3:1
     a non-text indicator needs. Its colour is a custom property, so redefining it on the
     ringed element suffices. */
  [class*="ring-blue-500"] {
    --tw-ring-color: var(--wx-link) !important;
  }
  /* a plain `outline-color` no ring token feeds. Its width and style only exist in the
     focus-visible state, so recolouring unconditionally touches nothing at rest. */
  [class*="outline-blue-500"],
  [class*="outline-blue-600"],
  [class*="outline-blue-700"] {
    outline-color: var(--wx-link) !important;
  }

  /* cards / modules / wells */
  [data-slot="card"],
  [data-slot="card-header"],
  [data-slot="card-content"],
  [data-testid="current-conditions"],
  [data-testid="current-widgets"],
  [data-testid="daily-forecast"],
  [data-testid="next-48-hours"],
  [data-testid="HealthAndActivitiesModule"],
  [data-testid="AirQualityIndex"],
  [data-testid$="Module"],
  [data-testid$="-container"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  [data-slot="card-header"] {
    background-color: transparent !important;
  }

  /* text */
  h1, h2, h3, h4, h5, h6,
  .text-gray-900,
  .text-black,
  .text-card-foreground,
  .text-foreground,
  b, strong {
    color: var(--wx-text) !important;
  }
  p, li, dt, dd, label, figcaption, small,
  .text-gray-700,
  .text-gray-800,
  .text-neutral-800 {
    color: var(--wx-text-2) !important;
  }
  /* list BULLETS and NUMBERS come from `::marker`, which no `li { color }` rule
     reaches. */
  li::marker {
    color: var(--wx-text-2) !important;
  }

  /* muted / secondary greys the app uses for metadata + captions */
  .text-gray-400,
  .text-gray-500,
  .text-gray-600,
  .text-neutral-500,
  .text-text-secondary,
  .text-muted-foreground,
  [class*="text-[#6f7585]"],
  [class*="text-[#8d8d8d]"] {
    color: var(--wx-text-muted) !important;
  }

  /* neutral text arrives as near-black inline rgb; saturated hues stay below. */
  [style*="color: rgb(37, 36, 34)"],
  [style*="color:#252422"],
  [style*="color: rgb(55, 55, 53)"] {
    color: var(--wx-text-2) !important;
  }
  [style*="color: rgb(103, 103, 103)"],
  [style*="color: rgb(141, 141, 141)"] {
    color: var(--wx-text-muted) !important;
  }
  /* SEMANTIC inline sunrise/sunset hues `.text-gray-900` flattens, ~2.2:1 natively here.
     The icon fill is currentColor, so `color` carries it. */
  [style*="color: rgb(203, 74, 20)"] {
    color: #ec9a5c !important;
    -webkit-text-fill-color: #ec9a5c !important;
  }
  [style*="color: rgb(163, 81, 112)"] {
    color: #d891ac !important;
    -webkit-text-fill-color: #d891ac !important;
  }
  /* an inline SEMANTIC rain teal on the label and, via -webkit-text-fill-color, its
     glyphs -- but they also ship `text-gray-900`, which our !important rule flattens. */
  [style*="color: rgb(63, 149, 178)"] {
    color: #5cb3d1 !important;
    -webkit-text-fill-color: #5cb3d1 !important;
  }

  /* Air Quality page (All Pollutants list + AQI status heading) */
  /* a NEAR-BLACK arbitrary token, not a saturated AQI hue, so lifting loses no semantics
     (the gauge arc and status dot keep theirs). */
  [data-testid="PollutantName"],
  [data-testid="AirQualityCategory"],
  [class*="text-[#2b2b2b]"],
  [class*="text-[#252422]"] {
    color: var(--wx-text) !important;
  }
  /* an already-remapped muted grey, pinned by its stable testid too against class
     rotation. */
  [data-testid="AirQualitySeverity"] {
    color: var(--wx-text-muted) !important;
  }
  /* on the AQI page this sits inside [data-testid="DonutChart"] and is already lifted;
     here the testid is on the node itself, so pin both the color and the SVG <text> fill. */
  [data-testid="DonutChartValue"],
  [data-testid="DonutChartValue"] text,
  [data-testid="DonutChartValue"] tspan {
    color: var(--wx-text) !important;
    fill: var(--wx-text) !important;
  }

  /* site-wide near-black text tokens (header, content strip, footer) */
  /* on EVERY page, via hashed module classes resolving to near-black tokens. Only
     title/label text is recoloured. */
  [data-testid="languageSelectorStatus"],
  [class*="LanguageSelector--unitDisplay"],
  [class*="LanguageSelector--LanguageSelectorStatus"],
  [data-testid="ContentMediaTitle"],
  [class*="ContentMedia--listItemTitle"],
  [class*="MediaObject--mediaCaptionCTA"] {
    color: var(--wx-text) !important;
  }
  [class*="PrivacyLinks"],
  [class*="PrivacyLinks"] a,
  footer [class*="Footer--link"] {
    color: var(--wx-text-2) !important;
  }
  [class*="PrivacyLinks"] a:hover,
  footer [class*="Footer--link"]:hover {
    color: var(--wx-link-hover) !important;
  }
  /* the mediaCaptionCTA link keeps its own treatment, matched more specifically. */
  [class*="MediaObject--mediaCaption"]:not([class*="mediaCaptionCTA"]) {
    color: var(--wx-text-2) !important;
  }
  /* its own #686c74, a grey the muted-token list does not carry. */
  [class*="MediaObject--mediaPublishDate"] {
    color: var(--wx-text-muted) !important;
  }
  /* a LIGHT gradient placeholder behind the lazy-loaded <img> -- a background-IMAGE, also
     shown on image-less promo fallbacks; the real <img> paints over it. */
  [class*="Image--gradient"] {
    background-image: linear-gradient(135deg, var(--wx-surface-2), var(--wx-surface)) !important;
  }

  /* the SPA content hubs ship it as an INLINE `background:` shorthand with no class. An
     attribute selector matches the RAW value, so the hex and rgb() spellings are two
     selectors and both must be listed. */
  [style*="linear-gradient(135deg, rgb(243, 243, 243)"],
  [style*="linear-gradient(135deg, #f3f3f3"],
  [style*="linear-gradient(135deg, #F3F3F3"] {
    background-image: linear-gradient(135deg, var(--wx-surface-2), var(--wx-surface)) !important;
  }
  /* a wrapper fill standing behind each map thumbnail until the raster arrives. */
  [class*="imagePlaceholder"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* <hr> with zero border and a light FILL, so the border reset never reaches them. */
  hr {
    background-color: var(--wx-border) !important;
  }

  /* temperature scale (semantic, NEUTRAL ends only) */
  /* the readouts are NEUTRAL -- high near-black, low grey -- not a saturated hue scale.
     Lift the high warm and the low cool; genuinely coloured values (alert reds, AQI/UV
     codes) are preserved. */
  [data-testid="TemperatureValue"] {
    color: var(--wx-text) !important;
  }
  /* the low is marked two ways and only one is inline: SPA rows wrap it in
     `text-gray-500`, older markup carries inline rgb(103, 103, 103). Both must be listed
     or the low and the high resolve to the same light. The class form must be TWO classes
     deep to out-rank the TemperatureValue lift, a direct declaration on the child. */
  [data-testid="daily-forecast"] [data-testid="TemperatureValue"][style*="103"],
  [data-testid="daily-forecast"] span[style*="rgb(103, 103, 103)"] [data-testid="TemperatureValue"],
  span[style*="rgb(103, 103, 103)"] > [data-testid="TemperatureValue"],
  span.text-gray-500 > [data-testid="TemperatureValue"] {
    color: #7fb4e6 !important;
  }
  /* the disc's inline background-color is the feels-like temperature and is preserved --
     and the site centres a DARK value on it across the whole scale, so the TemperatureValue
     lift is undone HERE only. */
  .rounded-full[style*="background-color"] [data-testid="TemperatureValue"] {
    color: #14181d !important;
    -webkit-text-fill-color: #14181d !important;
  }
  /* a SEMANTIC rain blue at ~3.5:1 on our surface; the coloured precip icons keep
     their hues. */
  [class*="text-[#007ea8]"],
  [class*="text-[#007EA8]"] {
    color: #45a8db !important;
  }
  /* the same percentages go muted grey when the chance is negligible: that grey/blue pair
     is the signal, so the muted ones must stay muted against the generic `p` rule. */
  [class*="text-[#9ca3af]"] {
    color: var(--wx-text-muted) !important;
  }

  /* the only place the severe-alert red is TEXT rather than a banner fill. The alert
     BANNER is untouched. */
  [class*="text-[var(--color-alert-severe)]"] {
    color: #f4695c !important;
  }

  /* links / accent */
  a,
  a:visited,
  .text-blue-500,
  .text-blue-600,
  .text-blue-700,
  /* brand-blue kickers the generic `p` rule flattens; #3a61cc is ~2.9:1 on our base. */
  .text-brand-light {
    color: var(--wx-link) !important;
  }
  /* the light end of that scale (#679ced / #aacbff / #d8e6fe) only lands on the BLACK
     hero plates as kickers, where the generic `p` rule greys it; the values read on dark,
     so they are restated verbatim rather than remapped. */
  .text-blue-400 {
    color: #679ced !important;
  }
  .text-blue-300 {
    color: #aacbff !important;
  }
  .text-blue-200 {
    color: #d8e6fe !important;
  }
  a:hover,
  a:focus {
    color: var(--wx-link-hover) !important;
  }
  /* `b, strong` and `a` are both (0,0,1) !important, but `b, strong` matches the CHILD
     directly and a matched rule beats an inherited value, so a bolded link must inherit the
     anchor's colour. */
  a strong,
  a b {
    color: inherit !important;
  }
  /* these headings are `a.Button--default` wrapping an <h2>, and the site's only hover
     feedback is fading the anchor's ink, which the <h2> inherits -- but `h1..h6` matches
     the heading DIRECTLY, so there is no hover unless restated. Brighten instead of
     dimming. Only these headers put a heading inside a Button--default anchor;
     article-card titles are `a.mediaLink`. */
  a[class*="Button--default"]:hover h1,
  a[class*="Button--default"]:hover h2,
  a[class*="Button--default"]:hover h3 {
    color: var(--wx-link-hover) !important;
  }
  /* a Tailwind GROUP-variant hover colour, compiled to a variant-prefixed name no plain
     selector reaches, while `h1..h6 / .text-gray-900` matches the same <h2> with
     !important. Scope the restore to the hovered `.group`: the variant class is in the
     class list at rest too. */
  .group:hover [class*="group-hover:text-[#1B4DE4]"] {
    color: var(--wx-link-hover) !important;
  }
  /* dark navy fills left alone, labelled `text-primary-foreground` i.e. near-white, which
     the `a` rule repaints. The paler tints are light surfaces, handled above. */
  .bg-brand-300,
  .bg-brand-400 {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* this CTA carries the SAME testid as its surrounding card, so the (0,1,0) card rule
     paints it the card colour; restating the brand fills wins that tie on source order.
     The arbitrary hover/active values are matched verbatim so the press states survive. */
  .bg-brand-400 {
    background-color: #0d142a !important;
  }
  .bg-brand-300 {
    background-color: #204794 !important;
  }
  [class*="hover:bg-[#252C3F]"]:hover {
    background-color: #252c3f !important;
  }
  [class*="active:bg-[#0C1226]"]:active {
    background-color: #0c1226 !important;
  }
  /* #0d142a is the design system's ink, not an accent. Today it only lands on <button>s
     (which take `button { color: inherit }`), but elsewhere it would render ~1.05:1. */
  .text-brand-dark,
  .text-brand-400 {
    color: var(--wx-text) !important;
  }
  /* this control paints with all three hooks of --color-brand-active at once:
     `text-brand-active` on the <button>, `border-l-brand-active` on the hairline,
     `fill-brand-active` on the globe. Two are flattened -- `button { color: inherit }` is
     UNLAYERED, and an unlayered normal declaration outranks one inside Tailwind's utilities
     layer whatever the specificity; the hairline takes `* { border-color }`. At >=768px the
     site swaps in neutral `md:` variants whose class tokens are present at EVERY width, so
     only the breakpoint can distinguish them. */
  @media (max-width: 767px) {
    [class*="text-brand-active"] {
      color: var(--wx-link) !important;
    }
    [class*="border-l-brand-active"] {
      border-left-color: var(--wx-link) !important;
    }
    [class*="fill-brand-active"] {
      fill: var(--wx-link) !important;
    }
  }

  /* restore the site's own `text-white` */
  /* `text-white` marks every piece of text sitting ON a saturated fill. It ships
     un-!important inside Tailwind's utilities layer, so our unlayered !important text rules
     beat it. Pure white is what the site paints and reads on every one of those fills. */
  .text-white {
    color: #ffffff !important;
  }
  /* the same convention one token further in. It reaches the page as link-blue because
     `button { color: inherit }` below is UNLAYERED and outranks the utility inside
     Tailwind's layer, so the button takes its wrapping `<a>`'s colour. */
  .text-primary-foreground {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* ...but the content hubs DO paint `bg-primary`, and our `--primary` remap makes that
     chip the light link blue, on which the white pinned above is 2.38:1. Where the element
     carries the fill itself it takes the dark `--primary-foreground`; the two-class
     selector keeps the dark-filled CTAs on white. */
  .bg-primary.text-primary-foreground {
    color: var(--primary-foreground) !important;
    -webkit-text-fill-color: var(--primary-foreground) !important;
  }

  /* data tables (hourly / 10-day details) */
  table,
  thead,
  tbody,
  tfoot {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border) !important;
  }
  thead th,
  th {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text) !important;
    border-color: var(--wx-border) !important;
  }
  tbody tr:nth-child(even) {
    background-color: var(--wx-surface-2) !important;
  }
  td {
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border) !important;
  }
  tbody tr:hover {
    background-color: #232a33 !important;
  }
  /* accordion detail rows in the 10-day list */
  [data-testid="daily-forecast"] details,
  [data-testid="daily-forecast"] summary,
  details[data-testid],
  summary[data-testid] {
    background-color: transparent !important;
    color: var(--wx-text-2) !important;
  }
  /* the row is a <button> painting a light fill in two states no static surface rule
     matches: :hover and aria-expanded="true". */
  [data-testid="daily-forecast"] button:hover,
  [data-testid="daily-forecast"] summary:hover,
  [data-testid="daily-forecast"] li:hover,
  [data-testid="daily-forecast"] button[aria-expanded="true"],
  [data-testid="daily-forecast"] [aria-expanded="true"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* STATE-VARIANT utilities compile to variant-prefixed names the plain `.bg-gray-*`
     selectors miss. The variant class is in the class list in EVERY state while the site
     only PAINTS it on hover / while open, so these MUST stay state-scoped: unconditionally
     they fill every row permanently and make :hover a no-op. */
  [data-testid="daily-forecast"] button:hover [class*="bg-gray-100"],
  [data-testid="daily-forecast"] button:hover [class*="bg-gray-200"],
  [data-testid="daily-forecast"] button:hover [class*="bg-neutral-100"],
  [data-testid="daily-forecast"] button:hover [class*="bg-neutral-200"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-gray-100"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-gray-200"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-neutral-100"],
  [data-testid="daily-forecast"] [aria-expanded="true"] [class*="bg-neutral-200"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* an INLINE background-color with no class, so no utility rule reaches it; the FILLED
     portion is a separate inline saturated blue and is data. */
  [style*="background-color: rgb(245, 245, 245)"] {
    background-color: var(--wx-border) !important;
  }
  /* the lifted `text-gray-900` percentage is centred ON this 8px pill, so the pill must
     carry light text while staying a visible cloud-grey; its WIDTH is the data. The dotted
     rail beside it uses the same colour as a background-IMAGE, which this substring does
     not match. */
  [style*="background-color: rgb(202, 217, 226)"] {
    background-color: #4f6a80 !important;
  }
  /* the flu-risk ramp's bottom step is achromatic #f2f2f2 -- invisible on white, the
     brightest thing on ours, so the ramp reads INVERTED. Sink that step alone; every
     chromatic step is data. */
  [style*="background-color: rgb(242, 242, 242)"] {
    background-color: var(--wx-border) !important;
  }
  /* forms / location search */
  input,
  textarea,
  select {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
    border-color: var(--wx-border-2) !important;
  }
  input::placeholder,
  textarea::placeholder {
    color: var(--wx-text-muted) !important;
    opacity: 1 !important;
  }
  /* EXCEPT range sliders: the radar and Cold-&-Flu / Allergy scrubbers are natively
     TRANSPARENT inputs stacked on the real, styled track, so an opaque fill makes the
     slider cover its own track.
     accent-color covers the opposite case: the radar Map Menu's transparency slider is left
     entirely to the UA, which paints the filled part in accent-color and the rest in its own
     light track. The UA ignores accent-color wherever the site styles the thumb itself, so
     the scrubbers above keep their own colours. */
  input[type="range"] {
    background-color: transparent !important;
    border-color: transparent !important;
    accent-color: var(--wx-link) !important;
  }

  /* the location-search dialog + its results list must be opaque dark */
  [data-testid="header-search"],
  [data-testid="header-search"] [role="dialog"],
  [data-testid="location-search"],
  [role="listbox"],
  [data-testid="header-search"] ul,
  [data-testid="header-search"] li {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  /* `bg-white!` has its !important inside Tailwind's utilities layer and BEATS an
     unlayered override. It resolves `var(--color-white)`, so redefine that ON the input:
     variable resolution is layer-agnostic, so their rule wins but computes our value. */
  [data-testid="header-search"] input,
  [data-testid="header-search"] input.bg-white,
  input[class*="bg-white"] {
    --color-white: #161d27 !important;
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  [data-testid="header-search"] input::placeholder,
  input[class*="bg-white"]::placeholder {
    color: var(--wx-text-muted) !important;
    opacity: 1 !important;
  }
  [data-testid="header-search"] li:hover,
  [data-testid="header-search"] a:hover,
  [role="option"]:hover,
  [role="option"][aria-selected="true"] {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  [data-testid="header-search"] a,
  [data-testid="header-search"] li,
  [role="option"] {
    color: var(--wx-text-2) !important;
  }
  /* a WHITE panel that only appears on focus+type, with a light-blue upsell card in it.
     Its rows already sit on the dark Listbox surface. */
  /* the white fill comes from a `[dir] .RecentLocations--container--<hash>` rule at
     (0,2,0) with !important, so the combobox ancestor + `--open` compound is needed. */
  [class*="SearchCombobox"] [class*="RecentLocations--container"][class*="RecentLocations--open"],
  [class*="RecentLocations--container"] {
    background-color: var(--wx-surface) !important;
  }
  [class*="RecentLocations--clearButton"] {
    color: var(--wx-link) !important;
  }
  [class*="LocationsUpsell--locationsUpsell"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="LocationsUpsell--locationsUpsell"] * {
    color: var(--wx-text-2) !important;
  }
  /* set through `-webkit-text-fill-color` too, so pin BOTH. Scoped to the flyout so the
     fragile `styles--` prefix cannot leak. */
  [class*="RecentLocations--container"] [class*="styles--locationName"],
  [class*="SearchCombobox"] [class*="styles--locationName"] {
    color: var(--wx-text) !important;
    -webkit-text-fill-color: var(--wx-text) !important;
  }
  /* the map-pin <svg> has NO fill attribute (so it paints the SVG default black) and the
     star is a currentColor STROKE. A favorited star keeps its amber. */
  [class*="SearchedLocations--locationIcon"],
  [class*="SearchedLocations--locationIcon"] path {
    fill: var(--wx-text-2) !important;
  }
  [class*="FavoriteStar--icon"] {
    color: var(--wx-text-muted) !important;
  }
  [class*="FavoriteStar--isFavorite"] [class*="FavoriteStar--icon"] {
    color: #fdc107 !important;
    fill: #fdc107 !important;
  }

  /* buttons */
  button {
    color: inherit;
  }
  /* keep these consistent with the chrome and ensure a visible hover */
  [data-testid="location-picker-trigger"],
  [data-testid="header-menu-button"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text) !important;
  }
  [data-testid="location-picker-trigger"]:hover,
  [data-testid="header-menu-button"]:hover {
    background-color: var(--wx-surface-2) !important;
  }

  /* settings / units menu (must be opaque) */
  /* NOTE: no case-insensitive attribute flag (`[... i]`) anywhere in this file -- the
     userstyles.org parser rejects it and drops the whole upload. */
  [data-settings-menu-trigger] + *,
  [role="menu"],
  [data-radix-popper-content-wrapper] > * {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  [role="menuitem"]:hover {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }
  /* a full-width WHITE panel with 170+ near-black region rows and icons. Only the legacy
     component carries `ExpandableMenu--inner`: the SPA units popover is a Radix popper
     handled above and its mobile drawer is dark already. */
  [class*="ExpandableMenu--inner"] {
    background-color: var(--wx-surface) !important;
  }
  /* a neutral picker with no semantic colours, so a blanket lift is safe: the active-unit
     tab is marked by its underline, not by colour. */
  [class*="ExpandableMenu--inner"] * {
    color: var(--wx-text-2) !important;
  }
  [class*="ExpandableMenu--inner"] svg,
  [class*="ExpandableMenu--inner"] svg * {
    fill: var(--wx-text-2) !important;
  }

  /* `visibility: hidden` until clicked, with a rotated-square notch painted by the arrow's
     ::before. Its colour swatches are inline fills and stay. */
  [class*="Popover--popover"],
  [class*="Popover--popover"] [data-popper-arrow]::before {
    background-color: var(--wx-surface-2) !important;
  }

  /* footer */
  footer,
  [data-testid="footer"],
  [data-component="footer"] {
    background-color: var(--wx-chrome) !important;
    color: var(--wx-text-2) !important;
  }
  /* ...but `header` / `footer` are BARE TAG selectors and the SPA also uses those tags
     for a card's own title row and source strip, transparent natively -- inside a
     <section>, and on the content hubs (/health, /travel) as a title row nested in plain
     <div>s. The page's real header/footer are DIRECT children of <main>, so neither
     descendant form can reach them. */
  section header,
  section footer,
  main div header {
    background-color: transparent !important;
  }
  footer a,
  [data-testid="footer"] a {
    color: var(--wx-text-2) !important;
  }
  footer a:hover {
    color: var(--wx-link-hover) !important;
  }
  /* an INLINE link inside a sentence, blue on both frontends; the link ROWS stay
     neutral. */
  footer p a,
  [class*="Footer--container"] p a {
    color: var(--wx-link) !important;
  }
  /* two of these four tiles are transparent-background artwork drawn for a WHITE page,
     and nothing in CSS reaches inside an <img>, so the white page goes back BEHIND them.
     The Weather Channel tile ships its own blue plate and Storm Radar its own dark rounded
     square, so both are left alone -- a plate would show through the latter's cut corners.
     One src match covers both frontends. */
  img[src*="the-weather-company"],
  img[src*="weather-underground"] {
    background-color: #ffffff !important;
    border-radius: 4px !important;
  }

  /* Taboola "More from weather.com" recommendation strip */
  /* white cards with hardcoded near-black titles; the thumbnail imagery stays. */
  .trc_rbox,
  .trc_rbox_outer,
  .trc_rbox_div,
  .trc_excludable,
  .trc_spotlight_item,
  .trc_related_container,
  .trc_popover,
  .trc_exclude_overlay {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  .video-title,
  .trc_el .video-title,
  .video-label,
  .trc_el,
  .syndicatedItem,
  .trc_rbox .branding,
  .trc_rbox_header_span {
    color: var(--wx-text-2) !important;
  }
  /* the ad disclosure's spans are pure black and sit outside every `.trc_*` surface class
     above. */
  .trc-widget-footer,
  .trc-widget-footer span,
  .trc-widget-header,
  .trc-widget-header span {
    color: var(--wx-text-muted) !important;
  }
  /* Taboola's brand kit writes its palette as INLINE custom properties on <html>, read
     by its late-injected rules at (0,4,0). Redefining the token on the widget root is
     specificity-agnostic and reaches every consumer (an !important author declaration also
     beats the NORMAL inline one). `.brand-name` is fed by no token and renders through
     `-webkit-text-fill-color`, so pin both properties. */
  .trc_rbox,
  [id*="taboola"] {
    --brand-color-text-primary: var(--wx-text-2) !important;
  }
  .tbl-brand-kit-branding-row .brand-name {
    color: var(--wx-text-muted) !important;
    -webkit-text-fill-color: var(--wx-text-muted) !important;
  }
  /* the Undo affordance is a <div>, not an <a>, so the link rules never reach it. */
  .trc_exclude_undo_btn {
    color: var(--wx-link) !important;
  }
  /* the `.video-title` !important lift above pins Taboola's own (0,4,0) hover rule flat.
     One class deeper than the brand-kit rule. */
  .trc_rbox .videoCube:hover .video-label-box .video-title.video-label {
    color: var(--wx-link-hover) !important;
  }
  /* a CSS-triangle whose left/right/top edges are transparent, so `* { border-color }`
     paints all four and the caret becomes a solid rectangle. */
  .trc_popover_arrow {
    border-color: transparent !important;
    border-bottom-color: var(--wx-surface) !important;
  }
  /* ...but the caret the eye sees is the arrow's `::after`, which neither `*` nor the
     rule above matches. Only one of top/bottom ever has a non-zero width (the `trc_bottom`
     / `trc_top` variants zero the other), so pinning both covers either direction without
     filling the box. Taboola also sets `color: #000` on matched CHILDREN of the popover,
     which beats the colour inherited from it. */
  .trc_popover_arrow::after {
    border-top-color: var(--wx-surface) !important;
    border-bottom-color: var(--wx-surface) !important;
  }
  .trc_popover_title_wrapper {
    background-color: var(--wx-surface-2) !important;
    border-bottom-color: var(--wx-border) !important;
  }
  .trc_popover_title_wrapper,
  .trc_popover_title,
  .popupContentWrapper,
  .trc_popover_content_wrapper,
  .trc_popover_content {
    color: var(--wx-text) !important;
  }
  /* the LOADING SKELETON: a light slab, a shimmer GIF in its `::before`, and `tbl-masker`
     boxes that mask the slab THROUGH THEIR BORDER -- fill and border must move together or
     `* { border-color }` draws a seam across each slab. */
  .tbl-placeholder-card {
    background-color: var(--wx-surface-2) !important;
  }
  .tbl-placeholder-card::before {
    background-color: var(--wx-surface-2) !important;
    background-image: none !important;
  }
  .tbl-masker {
    background-color: var(--wx-surface-2) !important;
    border-color: var(--wx-surface-2) !important;
  }
  /* four more light surfaces that only exist once a card plays or renders its reel.
     `tbl-ui-line` is the #333 divider drawn ON those plates, so it must be lifted in the
     same pass. `.video-cta-button` is deliberately left white: it sits over the video
     thumbnail, not our card, and Taboola pins `color: black !important` on its label. */
  [class*="tbl-editorial-video-container"] {
    background-color: var(--wx-surface) !important;
  }
  [class*="tbl-vignette-background-screen"] {
    background-color: var(--wx-base) !important;
  }
  [class*="tbl-text-under-title-background"],
  [class*="tbl-text-under-branding-background"] {
    background-color: var(--wx-surface-2) !important;
  }
  [class*="tbl-ui-line"] {
    background-color: var(--wx-border-2) !important;
  }

  /* Outbrain recommendation strips (international news lists) */
  /* these slots ship a white fill of their own and stay in flow even when the widget
     mounts EMPTY. */
  [id^="outbrain_widget"] {
    background-color: transparent !important;
  }
  .ob-widget,
  .ob-widget a {
    color: var(--wx-text-2) !important;
  }

  /* interactive radar map: the rebuilt Tailwind map UI */
  /* the /radar SPA map app writes its palette as Tailwind ARBITRARY hexes no named
     `bg-*` rule reaches, and the ACTIVE layer pill is one of them, within 1.05:1 of our
     card. Invert it as the chart tab strip is; its glyph carries `text-white`, a matched
     rule, so it is re-pointed with the label. Two other elements ship the same hex and must
     NOT flip -- the check badge and the carousel arrows sit ON a light map thumbnail -- so
     `border-[#c5c4c9]`, carried only by the active pills, is the discriminator. */
  [class*="bg-[#252422]"][class*="border-[#c5c4c9]"] {
    background-color: var(--wx-text) !important;
    color: var(--wx-chrome) !important;
    -webkit-text-fill-color: var(--wx-chrome) !important;
  }
  [class*="bg-[#252422]"][class*="border-[#c5c4c9]"] svg {
    color: var(--wx-chrome) !important;
  }
  /* the Map Type list marks its selected row with the same hex, discriminated by the
     `border-[#f2f2f2]` every row there carries. It sits INSIDE the darkened sheet, so it
     takes a row fill, not the inversion. */
  [class*="bg-[#252422]"][class*="border-[#f2f2f2]"] {
    background-color: var(--wx-border-2) !important;
  }
  /* a groove, an elapsed fill and a dashed NOW marker the border reset flattens. On dark
     the ordering inverts, so keep the past the more prominent. */
  [class*="bg-[#e8e8e8]"] {
    background-color: var(--wx-border-2) !important;
  }
  [class*="bg-[#b1b1b0]"] {
    background-color: var(--wx-text-muted) !important;
  }
  [class*="border-dashed"][class*="border-gray-900"] {
    border-color: var(--wx-text-muted) !important;
  }

  /* interactive radar map: floating control / insight panels */
  /* the map's two floating cards are its own UI, NOT the basemap. They ship white via
     HASHED module classes with no data-testid or role, so they are targeted by the STABLE
     module-name PREFIX. ROT RISK: if IBM changes the CSS-modules localIdentName format
     these stop matching -- accepted, since no stable hook exists. Links, layer thumbnails
     and the alert icon keep their own colours. */
  [class*="ControlPanel--controlContainer"],
  [class*="ControlPanel--noticeContainer"],
  [class*="InsightPanel--npContainer"],
  [class*="InsightPanel--insight"],
  [class*="LayerDetail--layerDetailContainer"],
  section.card[class*="Wrapper--radarWrapper"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text) !important;
  }
  [class*="InsightPanel--"]:not(a):not(button),
  [class*="ControlPanel--controlContainer"] *:not(a):not(button):not(img):not(svg):not(canvas),
  [class*="LayerDetail--"]:not(a):not(button) {
    color: var(--wx-text) !important;
  }
  /* ...but the InsightPanel `:not(a):not(button)` rule above is (0,1,2) and swallows two
     SEMANTIC accents, the amber alert icon and the blue "Read details". Scoped under
     npContainer (0,2,0) to out-rank it. */
  [class*="InsightPanel--npContainer"] [class*="InsightPanel--alertIcon"] {
    color: #ffb900 !important;
  }
  [class*="InsightPanel--npContainer"] [class*="InsightPanel--alertsLink"] {
    color: var(--wx-link) !important;
  }
  /* that chevron <svg> is matched DIRECTLY by the same broad rule, and a matched rule
     beats an inherited colour; its `Icon--iconWrapper` parent inherits correctly. */
  [class*="InsightPanel--npContainer"] [class*="InsightPanel--alertsLink"] [class*="InsightPanel--arrow"] {
    color: var(--wx-link) !important;
  }
  /* given the accent via its `textBlock` parent: the broad ControlPanel/LayerDetail rule
     carries two `:not()`s and sits at (0,1,2), so a single-class override loses the tie. */
  [class*="LayerDetail--textBlock"] [class*="LayerDetail--goPremium"] {
    color: var(--wx-link) !important;
  }

  /* the white fill comes from a doubled-class Helios rule that out-specifies the
     `section.card[class*="Wrapper--radarWrapper"]` rule above, so remap the Helios surface
     tokens ON the wrapper: variable resolution is specificity-agnostic, so their rule wins
     but COMPUTES our value. */
  [class*="Wrapper--radarWrapper"] {
    --backgroundPage: var(--wx-surface) !important;
    --backgroundCard: var(--wx-surface) !important;
  }
  /* <button> nodes, which the ControlPanel `:not(button)` rule excludes. */
  [class*="TimeLine--tickLabelButton"] {
    color: var(--wx-text-2) !important;
  }
  [class*="TimeLine--nowContainer"] [class*="TimeLine--tickLabelButton"] {
    color: var(--wx-text) !important;
  }
  /* a WHITE pill split by a 1px hairline, in a region deliberately left the site's own
     since it sits on the basemap; `* { border-color }` draws a dark bar across it. */
  [class*="Radar--zoomContainer"] button {
    border-color: rgb(206, 206, 208) !important;
  }

  /* marked ONLY by brand blue, which the border reset and the ControlPanel text rule
     (0,1,5, from its five `:not()`s) both flatten. Two classes deep to out-rank it. */
  [class*="LayerDetail--layerDetailContainer"] [class*="LayerDetail--selectedLayerTypeTitle"] {
    color: var(--wx-link) !important;
  }
  /* the expanded list rings the selection via `layerDetailImage`, the COLLAPSED round
     thumbnails via `layersIconContainer`. Scoped under `selectedLayerType`. */
  [class*="LayerDetail--selectedLayerType"] [class*="LayerDetail--layerDetailImage"],
  [class*="LayerDetail--selectedLayerType"] [class*="LayerDetail--layersIconContainer"] {
    border-color: var(--wx-link) !important;
  }
  /* shows through until each preview loads, and on every re-render of the list. */
  [class*="LayerDetail--thumbnailPlaceholder"] {
    background-color: var(--wx-surface-2) !important;
  }
  /* the legacy Toggle encodes its state ONLY in the track fill, with identical class
     names in both states -- OFF light, ON near-black -- so on a dark panel it reads exactly
     BACKWARDS, and the knob's checkmark inherits our lifted light text besides. `:checked`
     lives on a visually-hidden input that PRECEDES the track label, so match forward with
     adjacent siblings (CSS2 only -- no `~`); the label text is optional, hence both forms. */
  [class*="Toggle--track"] [class*="Toggle--switchWrap"] {
    background-color: var(--wx-border-2) !important;
  }
  [class*="Toggle--checkbox"]:checked + [class*="Toggle--track"] [class*="Toggle--switchWrap"],
  [class*="Toggle--checkbox"]:checked + [class*="Toggle--labelText"] + [class*="Toggle--track"] [class*="Toggle--switchWrap"] {
    background-color: var(--wx-link) !important;
  }
  [class*="Toggle--switch"] svg,
  [class*="Toggle--switch"] svg path {
    color: var(--wx-chrome) !important;
    fill: var(--wx-chrome) !important;
  }

  /* a 2px black border-bottom the `*` rule takes to 1.15:1. */
  [class*="TabList--tabSelected"] {
    border-bottom-color: var(--wx-text) !important;
  }
  /* the site marks the current tab only by the underline above, so a uniform lift keeps
     the distinction. */
  [class*="TabList--tab"] {
    color: var(--wx-text-2) !important;
  }
  /* the visual control IS the appearance:none <input>, and its `::after` dot is the only
     per-row selected marker. */
  [class*="Radio--inputClass"]:checked::after {
    background-color: var(--wx-text) !important;
  }
  /* the real track is `background: var(--PureWhite)`, remapped ON the track (variable
     resolution is specificity-agnostic). The grey elapsed fill and the Cold-&-Flu
     scrubber's purple risk bar are data, which is why the handle rule is scoped to the
     radar ControlPanel rather than every range input. */
  [class*="ControlPanel--controlContainer"] [class*="TimeLine--historyContainer"] {
    --PureWhite: var(--wx-surface-2);
  }
  /* Chromium and Gecko thumb pseudo-elements must be SEPARATE rules -- a mixed vendor
     selector list is invalid in both engines and drops the whole rule. */
  [class*="ControlPanel--controlContainer"] input[type="range"]::-webkit-slider-thumb {
    background-color: var(--wx-text) !important;
  }
  [class*="ControlPanel--controlContainer"] input[type="range"]::-moz-range-thumb {
    background-color: var(--wx-text) !important;
  }

  /* Cold & Flu "Extended Flu Forecast" timeline control */
  /* its date ticks are HTML spans and its play icon a path[fill="#2B2B2B"]. The flu-risk
     MAP and the severity dot stay untouched. */
  [class*="ExtendedFluForecast--controlContainer"],
  [class*="ExtendedAllergyForecast--controlContainer"] {
    background-color: var(--wx-surface) !important;
    color: var(--wx-text-2) !important;
  }
  [class*="FluRiskTimeLine--tickLabel"] {
    color: var(--wx-text-2) !important;
  }
  [class*="ExtendedFluForecast--controlContainer"] svg path[fill="#2B2B2B"],
  [class*="ExtendedFluForecast--controlContainer"] svg path[fill="#2b2b2b"] {
    fill: var(--wx-text-2) !important;
  }
  /* these are `<line stroke="currentColor">` resolved by a rule we cannot read, so the
     `svg line[stroke=...]` selectors at the bottom of this file cannot reach them. Only
     chrome lives in `g.tick`; the case bars are separate <rect>s and keep their data
     blue. */
  [class*="FluCDCReport--chart"] g.tick line {
    stroke: var(--wx-border-2) !important;
  }

  /* a WHITE box over the choropleth inheriting the card's lifted light text; the gradient
     swatch inside keeps its data colours. */
  [class*="ExtendedFluForecast--legendBox"],
  [class*="ExtendedAllergyForecast--legendBox"] {
    background-color: var(--wx-surface) !important;
  }

  /* 15-day allergy forecast SVG area chart */
  /* a white path fill plus a white -> light-purple gradient; the forecast LINE and its
     dots are data. */
  [data-testid="AllergyForecastChart"] path[fill="#FFFFFF"],
  [data-testid="AllergyForecastChart"] path[fill="#ffffff"],
  [class*="AllergyLineChart"] path[fill="#FFFFFF"],
  [class*="AllergyLineChart"] path[fill="#ffffff"] {
    fill: var(--wx-surface-2) !important;
  }
  [data-testid="AllergyForecastChart"] stop,
  [class*="AllergyLineChart"] stop {
    stop-color: var(--wx-surface-2) !important;
    stop-opacity: 1 !important;
  }

  /* every shadcn popover draws its notch as stacked `<svg class="fill-white">` polygons
     rather than a bordered CSS triangle, past both the border reset and the popover's own
     fill. Scope the remap to `[data-slot="popover-content"]`: a global `fill-white` remap
     would blacken the play glyphs the site paints over photo thumbnails. */
  [data-slot="popover-content"] svg[class*="fill-white"],
  [data-slot="popover-content"] svg[class*="fill-white"] polygon,
  [data-slot="popover-content"] svg[class*="fill-white"] path {
    fill: var(--wx-surface) !important;
  }

  /* black linework on a transparent PNG, unreachable by any selector. The hue-rotate
     returns a coloured partner mark to roughly its own hue, and the transparent background
     survives because filters leave alpha alone. */
  img.partner-logo {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* the widget ships its own light chrome: a white input pill, a navy logo, dark copy, a
     white scroll-fade shader. Stable third-party class names. */
  #dd-widget .dd-widget-title-text,
  #dd-widget .dd-widget-title-text span,
  #dd-widget .dd-widget-article-summary-content-wrapper,
  #dd-widget .dd-widget-article-summary-button {
    color: var(--wx-text) !important;
  }
  /* the shader must be OPAQUE for the absolutely-positioned button's full width or the
     clamped paragraph shows through the label. The widget publishes that width as
     `--dd-article-summary-button-width` (150px when unset), so this gradient ends at the
     same stop. */
  #dd-widget .dd-widget-article-summary-button-shader {
    background-image: linear-gradient(to right, rgba(28, 33, 40, 0), var(--wx-surface) calc(100% - var(--dd-article-summary-button-width, 150px))) !important;
  }
  #dd-widget .dd-widget-input-wrapper {
    background-color: var(--wx-surface-2) !important;
    border: 1px solid var(--wx-border) !important;
  }
  #dd-widget .dd-widget-branding-logo svg path {
    fill: var(--wx-text) !important;
  }
  /* a near-white fill authored in modern `color(srgb ...)` NOTATION. */
  #dd-widget .dd-widget-question-container,
  #dd-widget .dd-widget-question-container:hover {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text) !important;
  }

  /* DeeperDive's answer DIALOG (`.dd-dialog-wrapper`) is appended to <html> as a sibling
     of <body>, outside `#dd-widget`, and every surface, divider, ink and hover mix in it
     resolves from `--dd-*` tokens declared on :root (the widget ships a dark set behind
     `html.dd-dark`, which the page never applies). Remap the tokens; hex only, the widget
     does its own `color-mix()` on top. */
  :root {
    --dd-background-color: #1c2128 !important;
    --dd-text-color: #e6edf3 !important;
    --dd-text-meta-color: #8b949e !important;
    --dd-input-background: #161d27 !important;
    --dd-border-color: #2d333b !important;
    --dd-primary-color: #5fb0e6 !important;
    --dd-link-color: #5fb0e6 !important;
    --dd-widget-divider-color: #262c33 !important;
    --dd-result-divider-color: #262c33 !important;
    --dd-frame-divider-color: #262c33 !important;
    --dd-overlay-container: #161d27 !important;
    --dd-tooltip-background: #161d27 !important;
    --dd-overlay-backdrop-color: rgba(0, 0, 0, 0.6) !important;
    --dd-scrollbar-thumb: rgba(230, 237, 243, 0.3) !important;
    --dd-light-card-background: rgba(230, 237, 243, 0.05) !important;
    --dd-brand-logo-color: #e6edf3 !important;
    --dd-brand-icon-color: #8b949e !important;
  }
  /* the send button is a `--dd-primary-color` plate under a WHITE arrow: with the primary
     lifted to a light blue the arrow must go dark. */
  .dd-widget-input-send-button svg path {
    fill: var(--wx-chrome) !important;
  }
  /* the feedback tooltip is an inverted plate (`--dd-text-color` fill) whose caret is a
     hardcoded #1a1a1a path. */
  .dd-dialog .dd-tooltip svg path {
    fill: var(--wx-text) !important;
  }

  /* OpenWeb (Spot.IM) reactions + comments on news/video articles */
  /* OpenWeb renders inside an OPEN SHADOW ROOT on a custom element whose tag name is a
     per-publisher hash, so no rule of ours reaches inside. It is themeable anyway: the
     shadow root declares its palette as `--spotim-*` properties on `:host`, and an OUTER
     rule matching the host beats a `:host` rule. Match the host through its stable wrapper
     attributes, not the hashed tag name. `--spotim-color-scheme-l6` is the foreground base
     l1..l5 derive their translucent tints from. */
  [data-spotim-app] > *,
  [data-spotim-module] > * {
    --spotim-page-background-color: #1c2128 !important;
    --spotim-card-background-color: #1c2128 !important;
    --spotim-surface: #161d27 !important;
    --spotim-conversation-background-color: transparent !important;
    --spotim-input-background-color: #161d27 !important;
    --spotim-sayctrl-background-color: #161d27 !important;
    --spotim-sticky-say-control-background-color: #1c2128 !important;
    --spotim-list-item-background: #161d27 !important;
    --spotim-list-item-foreground: #2d333b !important;
    --spotim-overlay-background-color: #1c2128 !important;
    --spotim-extract-background-color: #161d27 !important;
    --spotim-embedded-comment-background-color: #161d27 !important;
    --spotim-embedded-comment-preview-background-color: #161d27 !important;
    --spotim-message-hover-menu-background-color: #161d27 !important;
    --spotim-color-scheme-g1: #1c2128 !important;
    --spotim-color-scheme-g2: #e6edf3 !important;
    --spotim-color-scheme-l6: #e6edf3 !important;
    --spotim-color-scheme-l6-rgb: 230, 237, 243 !important;
    --spotim-color-scheme-l100: #14181d !important;
    --spotim-text-color-default: #e6edf3 !important;
    --spotim-message-text-color: #c4cdd6 !important;
    --spotim-text-color-muted: #8b949e !important;
    --spotim-text-color-x-muted: #8b949e !important;
    --spotim-text-color-xx-muted: #8b949e !important;
    --spotim-text-color-product-header: #e6edf3 !important;
    --spotim-reactions-title-color: #e6edf3 !important;
    --spotim-reactions-reaction-text-color: #8b949e !important;
    --spotim-pitc-header-color: #e6edf3 !important;
    --spotim-pitc-top-comment-color: #e6edf3 !important;
    --spotim-user-image-font-color: #c4cdd6 !important;
    --spotim-ads-text-color: #8b949e !important;
    --spotim-ads-footer-color: #8b949e !important;
    --spotim-share_icon_color: #c4cdd6 !important;
    --spotim-border-color: #262c33 !important;
    --spotim-border-color-muted: #262c33 !important;
    --spotim-strong-border-color: #2d333b !important;
    --spotim-say-control-border-color: #2d333b !important;
    --spotim-message-separator-color: #262c33 !important;
    --spotim-input-separator-color: #2d333b !important;
    --spotim-star-color-empty: #2d333b !important;
    --spotim-progress-bar-background-color: #262c33 !important;
    --spotim-skeleton-background-color: #262c33 !important;
    --spotim-skeleton-foreground-color: #1c2128 !important;
    --spotim-content-loader-primary-color: #1c2128 !important;
    --spotim-content-loaders-secondary-color: #262c33 !important;
    --spotim-modal-backdrop-background-color: rgba(13, 17, 23, 0.7) !important;
    --spotim-safeframe-modal-backdrop-color: rgba(13, 17, 23, 0.7) !important;
  }
  /* a SECOND shadow root whose disc is a hardcoded `background-color:#fff` with no
     custom property behind it, so the vars above cannot reach it. `filter: invert()` would
     darken it -- but a filtered element becomes the containing block for its
     `position: fixed` descendants and the bell stops floating; `opacity` creates none. */
  div[data-spot-im-shadow-host="floating-bell"] {
    opacity: 0.35 !important;
  }

  /* support.weather.com help centre */
  /* `domain("weather.com")` also matches the support subdomain, a separate Salesforce
     Experience Cloud app. Our text lifts reach it but none of our surfaces do. Its navy
     hero band, brand logos and blue/white filter chips are the site's own and stay. */
  .cFeedbackCommunityV2HomeContent,
  .cFeedbackCommunityV2Article,
  .brands,
  .articles-list,
  .article-card,
  .alert-detail-card,
  .sidebar,
  .search-form,
  .footer-v2,
  .slds-modal__content,
  .slds-modal__header,
  .slds-modal__footer {
    background-color: var(--wx-surface) !important;
  }
  /* its headline links are the Salesforce navy #0a3fa8, ~2:1 on that surface */
  .brand-title,
  .article-title {
    color: var(--wx-link) !important;
  }
  .brand-title:hover,
  .article-title:hover {
    color: var(--wx-link-hover) !important;
  }
  /* the footer's own #333 / #666 labels sit outside every text rule above */
  .footer-v2 .connect-label,
  .footer-v2 .footer-copyright {
    color: var(--wx-text-2) !important;
  }
  /* the data-rights row is the footer's one LINK-coloured row (Salesforce navy) among
     #333 siblings; two classes deep to out-rank its own `text-gray-600` utility, so the
     hover arm has to be restated at the same weight. */
  .footer-v2 .footer-data-links a {
    color: var(--wx-link) !important;
  }
  .footer-v2 .footer-data-links a:hover {
    color: var(--wx-link-hover) !important;
  }
  /* a WHITE pill on the navy bar, so it has to keep dark ink; the anchor rule would paint
     it link blue at 2.4:1 on its own fill. */
  .nav-pill-active {
    color: #204794 !important;
  }
  /* its SIBLINGS sit on that same navy band, painted white at 72% alpha. The band is
     brand colour and is never darkened, so the label goes back to white. `.link-style` is
     used ONLY by these four, and the site gives them no hover state, so full white keeps
     the nav's own hue rather than the blue `a:hover` forces. */
  .link-style {
    color: rgba(255, 255, 255, 0.72) !important;
  }
  .link-style:hover {
    color: #ffffff !important;
  }
  /* Salesforce-dark accents below 3:1 on the darkened surfaces. The platform badges are
     keyed on data-platform, since all three share one class. */
  .ai-help-title {
    color: var(--wx-text) !important;
  }
  /* an `oklch()` grey at 2.38:1 on the page base. */
  .banner-text .text-gray {
    color: var(--wx-text-2) !important;
  }
  .brand-badge {
    color: var(--wx-text-muted) !important;
  }
  /* the badge is an OUTLINE chip: rim and label share one hue, so the rim is restated
     with the ink or the blanket border reset leaves a grey ring around a coloured word. */
  .platform-badge[data-platform="iOS"] {
    color: #6ea8f0 !important;
    border-color: #6ea8f0 !important;
  }
  .platform-badge[data-platform="Android"] {
    color: #57bb7e !important;
    border-color: #57bb7e !important;
  }
  .platform-badge[data-platform="Web"] {
    color: #b18ce0 !important;
    border-color: #b18ce0 !important;
  }
  /* authored rich text: every run is a `<span style="color: …">` pasted from an editor
     (#000000, #1a1a1a, #1d1c1d, #434343 and the Docs / Slack link blues #1155cc, #1264a3
     have all shipped), so the literal set is open-ended and the tag-level text rules
     never reach it. No inline ink in a support body is semantic: lift all of it, links
     to the link colour, heading runs (`<h2><strong><span>`) to the primary ink. The
     inline declaration sits on the span, so a heading lift on the <h2> never wins. */
  .article-body [style*="color:"],
  .alert-detail-card [style*="color:"] {
    color: var(--wx-text-2) !important;
  }
  .article-body h1 [style*="color:"],
  .article-body h2 [style*="color:"],
  .article-body h3 [style*="color:"],
  .article-body h4 [style*="color:"] {
    color: var(--wx-text) !important;
  }
  .article-body a[style*="color:"],
  .article-body a [style*="color:"] {
    color: var(--wx-link) !important;
  }
  /* the same paste carries `background-color: #ffffff` / `#f3f3f3` plates on whole
     paragraphs and headings; table headers keep the plate the cell rule gives them. */
  .article-body [style*="background-color"]:not(th):not(td) {
    background-color: transparent !important;
  }
  /* none of this metadata carries a text-* utility, so the muted-token list above cannot
     reach it. */
  .filter-label,
  .other-brands-label,
  .articles-count,
  .article-meta,
  .article-meta span,
  .meta-dot,
  .vote-item,
  .vote-item span,
  .helpful-label {
    color: var(--wx-text-muted) !important;
  }
  /* a plain <span> painted in an `oklch()` slate no text rule of ours reaches; muted
     keeps it quieter than the links, as the site intends. */
  .breadcrumb-item.active,
  .breadcrumb-item.active span {
    color: var(--wx-text-muted) !important;
  }
  /* white pills with dark ink, inverting to a navy fill with a white label when selected,
     so on dark the control reads backwards. The `.active` chip also ships `bg-blue-600`;
     matching the pair keeps us above the site's own two-class rule. */
  .filter-btn {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border-2) !important;
  }
  /* the chip's only hover feedback is label and rim going navy, which the restated colour
     above would pin flat. */
  .filter-btn:hover {
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  /* must come AFTER the hover rule: both are (0,2,0), so source order decides, and
     hovering the selected chip must not paint its label the colour of its fill. */
  .filter-btn.active,
  .filter-btn.active.bg-blue-600 {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
  }
  /* white pills whose hairline `* { border-color }` had already darkened. */
  .vote-btn,
  .action-btn {
    background-color: var(--wx-surface-2) !important;
    color: var(--wx-text-2) !important;
    border-color: var(--wx-border-2) !important;
  }
  /* each has its OWN hover move and the restatement above pins whichever property carries
     it, so mirror them one for one. */
  .vote-btn:hover {
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  /* the PRESSED vote is a `--primary` fill under a `--primary-foreground` label, which the
     resting restatement above would pin flat. */
  .vote-btn.vote-btn-active,
  .vote-btn.vote-btn-active:hover {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
    border-color: var(--wx-link) !important;
  }
  .vote-btn.vote-btn-success {
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  .action-btn:hover {
    background-color: var(--wx-border) !important;
  }
  /* the OUTLINE half of the "Can't find what you're looking for?" pair -- white fill, navy
     label and rim, invisible-on-white by design. */
  .contact-btn {
    background-color: transparent !important;
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }
  /* its hover is the outline-to-filled flip, which the transparent fill above pins. */
  .contact-btn:hover {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
  }
  /* natively an outline pair beside the filled "Ok". Scoped to the modal so the buttons
     carrying the class with a fill of their own keep it. */
  .slds-modal .slds-button_neutral {
    background-color: transparent !important;
    color: var(--wx-link) !important;
    border-color: var(--wx-border-2) !important;
  }
  .slds-modal .slds-button_neutral:hover {
    background-color: var(--wx-link) !important;
    color: var(--wx-chrome) !important;
  }
  /* white ON a white search form: no plate at all natively, just a navy label and
     magnifier inside the pill. */
  .search-form button {
    background-color: transparent !important;
    color: var(--wx-link) !important;
  }
  /* every in-app navigation mounts this spinner, whose plate is rgba(255,255,255,.8) for
     as long as the route takes. */
  .siteforceLoadingBalls {
    background-color: rgba(13, 17, 23, 0.85) !important;
  }

  /* navy label AND rim natively (1.9:1 on the dark card); both lift to the link tone.
     The rim is otherwise swallowed by the blanket border reset. Keep this the ONLY
     .brand-badge-outline border-color declaration -- a same-specificity twin earlier in
     the sheet loses to it silently. */
  .brand-badge-outline {
    color: var(--wx-link) !important;
    border-color: var(--wx-link) !important;
  }

  /* Keep weather imagery / data viz untouched: maps (DynamicMap + Mapbox tiles),
     condition icons and photos must render their real pixels. */
  img,
  picture,
  video,
  canvas,
  [data-testid="DynamicMap"],
  [data-testid="DynamicMap"] *,
  .mapboxgl-map,
  .mapboxgl-canvas,
  [class*="mapbox"] {
    background-color: transparent !important;
  }
  [data-testid="DynamicMap"] *,
  .mapboxgl-map * {
    border-color: transparent !important;
  }
  /* ...but the map's own UI is NOT basemap: the rules above erase the location pin and
     the "Now" chip drawn on top of it. Both carry a data-testid, so they are restored at
     (0,2,0), above the (0,1,0) neutralizers. */
  [data-testid="DynamicMap"] [data-testid="LocationPin"] {
    background-color: #1944de !important;
    border-color: #ffffff !important;
  }
  [data-testid="DynamicMap"] [data-testid="DynamicMapTimeStamp"] {
    background-color: rgba(13, 17, 23, 0.85) !important;
  }

  /* SVG data-viz chrome: the site's own charts/gauges (NOT raster maps). White track /
     grid / plot chrome is darkened; the COLOURED data is preserved verbatim. */

  /* (0) this chart is a <canvas>: each hour column is a full-height #eeeeee TRACK with
     the precipitation as a coloured tip at its base. A canvas is unreachable by
     fill/background rules but IS filterable: invert + 180deg hue-rotate maps the track
     near-black while returning saturated data colours to very near themselves. The stable
     `aria-label` keeps the filter off everything else. */
  [aria-label="Precipitation Intensity Chart"] canvas {
    filter: invert(1) hue-rotate(180deg);
  }
  /* a <canvas> too -- gridlines, axis labels, caption and case bars are all pixels -- and
     the same chain keeps each as subtle or legible against dark as against white. */
  [data-testid="FluCDCReportModule"] canvas {
    filter: invert(1) hue-rotate(180deg);
  }

  /* (1) semicircle gauge: darken the light track arc; the coloured value arc keeps its
     own stroke. */
  [data-testid="SemiCircleGauge"] path[stroke="#E7ECF1"],
  [data-testid="SemiCircleGauge"] path[stroke="#e7ecf1"] {
    stroke: var(--wx-border-2) !important;
  }

  /* (2) donut chart: the track ring is the first circle; the coloured value arc is a
     second circle with an inline stroke. */
  [data-testid="DonutChart"] circle[stroke="#E7ECF1"],
  [data-testid="DonutChart"] circle[class*="stroke-[#E7ECF1]"],
  [data-testid="DonutChart"] circle[class*="stroke-[#e7ecf1]"],
  /* the track ring is also painted by a module class with NO stroke attribute, which the
     attribute selectors above cannot match. */
  [data-testid="DonutChart"] circle[class*="DonutChart--track"],
  circle[class*="DonutChart--track"],
  .stroke-\[\#E7ECF1\],
  .stroke-\[\#e7ecf1\] {
    stroke: var(--wx-border-2) !important;
  }
  [data-testid="DonutChart"] circle[fill="#fff"],
  [data-testid="DonutChart"] circle[fill="#ffffff"],
  [data-testid="DonutChart"] circle[fill="white"] {
    fill: var(--wx-surface) !important;
  }
  /* (2b) the gauge CENTER VALUE is an SVG <text> coloured by a `fill-text-*` utility
     resolving to a NEAR-BLACK token. */
  [data-testid="DonutChart"] text,
  [data-testid="DonutChart"] tspan,
  [data-testid="SemiCircleGauge"] text,
  [data-testid="SemiCircleGauge"] tspan,
  svg text[class*="fill-text-"],
  svg tspan[class*="fill-text-"] {
    fill: var(--wx-text) !important;
  }

  /* (2c) the WIND COMPASS is a bare <svg> with no testid: a dashed dial ring, an "N"
     label, and the needle as three near-black shapes. The ring drops to the component
     border, as subtle on dark as #d1d5db was on white. */
  svg line[stroke="#1f2937"] {
    stroke: var(--wx-text) !important;
  }
  svg circle[fill="#1f2937"],
  svg polygon[fill="#1f2937"] {
    fill: var(--wx-text) !important;
  }
  svg text[fill="#6b7280"] {
    fill: var(--wx-text-muted) !important;
  }
  /* (2d) the sun/moon arcs draw their PATH as a #111827 stroke with #111827 end dots over
     a #f3f4f6 ground rect, with #d1d5db dotted guides. */
  svg path[stroke="#111827"] {
    stroke: var(--wx-text) !important;
  }
  svg circle[fill="#111827"] {
    fill: var(--wx-text) !important;
  }
  svg circle[stroke="#d1d5db"],
  svg line[stroke="#d1d5db"] {
    stroke: var(--wx-border-2) !important;
  }

  /* (3) chart plot backgrounds shipped as a white <rect>; data bars keep their fill.
     Raster maps are <canvas>/Mapbox tiles (no <svg><rect>), so this never touches them. */
  svg > rect[fill="white"],
  svg > rect[fill="#fff"],
  svg > rect[fill="#ffffff"],
  svg rect[fill="#F2F2F2"],
  svg rect[fill="#f2f2f2"],
  svg rect[fill="#f3f4f6"],
  svg rect[fill="#F3F4F6"],
  svg rect[fill="#E7ECF1"],
  svg rect[fill="#e7ecf1"] {
    fill: var(--wx-surface-2) !important;
  }
  /* gauge tick marks / faint gridline strokes shipped as light #E7ECF1 */
  [data-testid="SemiCircleGauge"] line[stroke="#E7ECF1"],
  [data-testid="SemiCircleGauge"] line[stroke="#e7ecf1"],
